let database;
function openDatabase(){return database||=new Promise((resolve,reject)=>{const req=indexedDB.open('wastewise-scans',1);req.onupgradeneeded=()=>req.result.createObjectStore('scans',{keyPath:'id'});req.onsuccess=()=>{req.result.onversionchange=()=>{req.result.close();database=null;};resolve(req.result);};req.onerror=()=>{database=null;reject(req.error);};req.onblocked=()=>{database=null;reject(Error('Close another WasteWise tab to enable scan storage.'));};});}
async function transaction(mode,action){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction('scans',mode),request=action(tx.objectStore('scans'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||request.error);tx.onabort=()=>reject(tx.error||Error('Scan storage could not be updated.'));});}
export const scanStore={save:scan=>transaction('readwrite',store=>store.put(structuredClone(scan))),get:id=>transaction('readonly',store=>store.get(id)),list:()=>transaction('readonly',store=>store.getAll()),remove:id=>transaction('readwrite',store=>store.delete(id))};
